export function partSkinRegions(part,layer=0){const [w,h,d]=part.dims,full=part.fullWidth||w,cut=part.cut||0,x=part.cutX||0,[u,v]=layer?part.overlay:part.uv;return [[u+d+x,v,w,d],[u+d+full+x,v,w,d],[u,v+d+cut,d,h],[u+d+x,v+d+cut,w,h],[u+d+full,v+d+cut,d,h],[u+2*d+full+full-x-w,v+d+cut,w,h]];}
export function partHeadSkin(source,part){const canvas=document.createElement('canvas');canvas.width=canvas.height=64;const ctx=canvas.getContext('2d');ctx.imageSmoothingEnabled=false;const destinations=[[8,0],[16,0],[0,8],[8,8],[16,8],[24,8]];for(let layer=0;layer<2;layer++){if(part.role==='head'){ctx.drawImage(source,0,0);break;}for(const [i,region]of partSkinRegions(part,layer).entries()){const [x,y]=destinations[i];ctx.drawImage(source,...region,x+layer*32,y,8,8);}}for(const [x,y]of destinations){const data=ctx.getImageData(x,y,8,8);for(let i=3;i<data.data.length;i+=4)data.data[i]=255;ctx.putImageData(data,x,y);}return canvas.toDataURL('image/png');}
const nextId=(items,prefix)=>prefix+(Math.max(0,...items.map(o=>+o.id.slice(1)))+1);
